#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> set1 = {1, 3, 5, 7};
    std::vector<int> set2 = {2, 4, 6, 8};
    std::vector<int> mergedSet;
    mergedSet.reserve(set1.size() + set2.size());
    std::merge(set1.begin(), set1.end(), set2.begin(), set2.end(), std::back_inserter(mergedSet));
    for (const auto& num : mergedSet) {
        std::cout << num << ' ';
    }
    return 0;
}
